/**
 * Plan Feature Extension
 *
 * /plan command that:
 * 1. Prompts for a feature name
 * 2. Creates a plan/<feature-name>.md file with a plan template
 * 3. Opens the plan file in VS Code
 * 4. Opens the plan content in the pi editor
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { existsSync } from "node:fs";

const PLAN_DIR = "plan";

function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function generatePlanTemplate(featureName: string, timestamp: string): string {
  return `# ${featureName}

> **Status:** Draft  
> **Created:** ${timestamp}

## Overview

<!-- Briefly describe what this feature does and why it's needed -->

## Motivation

<!-- Why are we building this? What problem does it solve? -->

## Requirements

<!-- Concrete requirements. What must this feature do? -->

- 
- 

## Design / Approach

<!-- High-level design decisions, data flow, architecture choices -->

### Files to modify

<!-- Use \`tree\` or list files that will be changed -->

<!--
\`\`\`
path/to/file1.py - Description of change
path/to/file2.py - Description of change
\`\`\`
-->

### Database changes (if any)

<!-- Migration scripts, new tables, schema changes -->

### API changes (if any)

<!-- New endpoints, modified responses, request/response shapes -->

## Implementation Steps

1. 
2. 
3. 

## Testing Plan

<!-- How will this be tested? Unit tests, integration tests, manual steps -->

- [ ] Unit tests added/updated
- [ ] Integration tests pass
- [ ] Manual smoke test

## Edge Cases & Risks

<!-- Things that could go wrong, edge cases to handle -->

- 

## References

<!-- Links to docs, issues, related PRs -->

`;
}

export default function planFeatureExtension(pi: ExtensionAPI) {
  pi.registerCommand("plan", {
    description: "Create a new feature plan",
    handler: async (_args, ctx) => {
      // Step 1: Ask for the feature name
      const featureName = await ctx.ui.input(
        "Feature name:",
        "e.g. Add user authentication",
      );

      if (!featureName?.trim()) {
        ctx.ui.notify("Plan creation cancelled.", "warning");
        return;
      }

      const trimmedName = featureName.trim();
      const slug = slugify(trimmedName);
      const planDir = join(ctx.cwd, PLAN_DIR);
      const planPath = join(planDir, `${slug}.md`);

      // Step 2: Check if plan already exists
      if (existsSync(planPath)) {
        const overwrite = await ctx.ui.confirm(
          "Plan exists",
          `"${slug}.md" already exists. Open it instead?`,
        );

        if (overwrite) {
          // Open existing plan
          await pi.exec("code", [planPath]);
          ctx.ui.setEditorText(planPath);
          ctx.ui.notify(`Opening existing plan: plan/${slug}.md`, "info");
          return;
        }

        ctx.ui.notify("Plan creation cancelled.", "warning");
        return;
      }

      // Step 3: Create plan directory and file
      try {
        await mkdir(planDir, { recursive: true });

        const timestamp = new Date().toISOString().replace("T", " ").slice(0, 19);
        const content = generatePlanTemplate(trimmedName, timestamp);

        await writeFile(planPath, content, "utf-8");

        // Step 4: Open in VS Code
        const result = await pi.exec("code", [planPath]);

        if (result.code === 0 || existsSync("/snap/bin/code")) {
          ctx.ui.notify(
            `Plan created and opened in VS Code: plan/${slug}.md`,
            "success",
          );
        } else {
          ctx.ui.notify(
            `Plan created: plan/${slug}.md (VS Code not available)`,
            "info",
          );
        }

        // Step 5: Load the plan content into pi's editor for context
        ctx.ui.setEditorText(content);

        // Step 6: Send a message to kick off planning discussion
        pi.sendUserMessage(
          `I've created a plan for "${trimmedName}" at plan/${slug}.md. Let's review and flesh out the requirements together.`,
        );
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        ctx.ui.notify(`Failed to create plan: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify(
      'Use /plan to create a feature plan. Plans are saved to "plan/" and opened in VS Code.',
      "info",
    );
  });
}

/**
 * Implement Plan Extension
 *
 * /implement command that:
 * 1. Lists available plan files from plan/ directory (excluding plan/implemented/)
 * 2. Loads the selected plan and sends it to the agent for implementation
 * 3. After implementation, moves the plan to plan/implemented/ with timestamp
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { readFile, mkdir, rename } from "node:fs/promises";
import { join, basename, dirname, extname } from "node:path";
import { readdirSync, existsSync } from "node:fs";

const PLAN_DIR = "plan";
const IMPLEMENTED_DIR = "plan/implemented";

function timestamp(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function listPlans(cwd: string): string[] {
  const planDir = join(cwd, PLAN_DIR);
  if (!existsSync(planDir)) return [];

  try {
    return readdirSync(planDir).filter(
      (f) => f.endsWith(".md"),
    );
  } catch {
    return [];
  }
}

export default function implementPlanExtension(pi: ExtensionAPI) {
  let currentPlanPath: string | null = null;
  let currentPlanName: string | null = null;

  function persistState(): void {
    pi.appendEntry("implement-plan", {
      planPath: currentPlanPath,
      planName: currentPlanName,
    });
  }

  async function moveToImplemented(
    planPath: string,
    cwd: string,
  ): Promise<string | null> {
    const implementedDir = join(cwd, IMPLEMENTED_DIR);
    await mkdir(implementedDir, { recursive: true });

    const name = basename(planPath, extname(planPath));
    const ts = timestamp().replace(/:/g, "");
    const newName = `${name}-done-${ts}.md`;
    const newPath = join(implementedDir, newName);

    await rename(planPath, newPath);
    return newPath;
  }

  // /implement - pick a plan and start implementing
  pi.registerCommand("implement", {
    description: "Select a plan and start implementing it. Pass a name to match in plan/ (e.g. removing-control-tab) or a relative path (e.g. plan/show-funds.md).",
    handler: async (_args, ctx) => {
      const requested = _args?.trim();
      let planPath: string;
      let selectedPlan: string;

      if (requested) {
        // If the argument looks like a path (contains / or .md), resolve it relative to cwd
        if (requested.includes("/") || requested.endsWith(".md")) {
          const resolved = join(ctx.cwd, requested);
          if (!existsSync(resolved)) {
            ctx.ui.notify(
              `Plan file not found: ${requested}`,
              "warning",
            );
            return;
          }
          planPath = resolved;
          selectedPlan = basename(resolved);
        } else {
          // Otherwise, match against plans in the plan/ directory
          const plans = listPlans(ctx.cwd);

          if (plans.length === 0) {
            ctx.ui.notify(
              'No plans found in plan/. Use /plan to create one first.',
              "warning",
            );
            return;
          }

          const match = plans.find(
            (p) =>
              p.toLowerCase().includes(requested.toLowerCase()) ||
              p.replace(/\.md$/, "").toLowerCase() ===
                requested.toLowerCase().replace(/\.md$/, ""),
          );
          if (!match) {
            ctx.ui.notify(
              `No plan matching "${requested}". Use /implement without args to pick.`,
              "warning",
            );
            return;
          }
          planPath = join(ctx.cwd, PLAN_DIR, match);
          selectedPlan = match;
        }
      } else {
        // Show selection dialog
        const plans = listPlans(ctx.cwd);

        if (plans.length === 0) {
          ctx.ui.notify(
            'No plans found in plan/. Use /plan to create one first.',
            "warning",
          );
          return;
        }

        const choice = await ctx.ui.select(
          "Pick a plan to implement:",
          plans,
        );
        if (!choice) {
          ctx.ui.notify("No plan selected.", "info");
          return;
        }
        selectedPlan = choice;
        planPath = join(ctx.cwd, PLAN_DIR, selectedPlan);
      }

      try {
        const content = await readFile(planPath, "utf-8");

        // Store current plan
        currentPlanPath = planPath;
        currentPlanName = selectedPlan;
        persistState();

        ctx.ui.notify(
          `Implementing: ${selectedPlan}`,
          "info",
        );

        // Send the plan to the agent for implementation
        pi.sendUserMessage(
          `Implement the following plan. After completing all steps, let me know so I can mark it as done.\n\n${content}`,
        );
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        ctx.ui.notify(`Failed to read plan: ${message}`, "error");
      }
    },
  });

  // /implemented - mark current plan as done and move to plan/implemented/
  pi.registerCommand("implemented", {
    description:
      "Mark the current plan as implemented (moves to plan/implemented/)",
    handler: async (_args, ctx) => {
      if (!currentPlanPath) {
        ctx.ui.notify(
          "No plan is currently being implemented. Use /implement first.",
          "warning",
        );
        return;
      }

      if (!existsSync(currentPlanPath)) {
        ctx.ui.notify(
          `Plan file no longer exists: ${currentPlanPath}`,
          "error",
        );
        currentPlanPath = null;
        currentPlanName = null;
        persistState();
        return;
      }

      const movedPath = await moveToImplemented(currentPlanPath, ctx.cwd);

      if (movedPath) {
        ctx.ui.notify(
          `Plan implemented and archived: implemented/${basename(movedPath)}`,
          "success",
        );
      }

      currentPlanPath = null;
      currentPlanName = null;
      persistState();
    },
  });

  // Prompt to mark as done after agent finishes
  pi.on("agent_end", async (event, ctx) => {
    if (!currentPlanPath || !ctx.hasUI) return;

    // Check if the plan file still exists (it might have been moved already)
    if (!existsSync(currentPlanPath)) {
      currentPlanPath = null;
      currentPlanName = null;
      persistState();
      return;
    }

    const done = await ctx.ui.confirm(
      "Plan Implemented?",
      `Is "${currentPlanName}" fully implemented? This will move it to plan/implemented/.`,
    );

    if (done) {
      const movedPath = await moveToImplemented(currentPlanPath, ctx.cwd);

      if (movedPath) {
        ctx.ui.notify(
          `Plan archived: implemented/${basename(movedPath)}`,
          "success",
        );
      }

      currentPlanPath = null;
      currentPlanName = null;
      persistState();
    } else {
      ctx.ui.notify(
        `Plan "${currentPlanName}" still in progress. Use /implemented when done.`,
        "info",
      );
    }
  });

  // Restore state on session resume
  pi.on("session_start", async (_event, ctx) => {
    const entries = ctx.sessionManager.getEntries();

    const implEntry = entries
      .filter(
        (e: { type: string; customType?: string }) =>
          e.type === "custom" && e.customType === "implement-plan",
      )
      .pop() as
      | { data?: { planPath?: string | null; planName?: string | null } }
      | undefined;

    if (implEntry?.data) {
      currentPlanPath = implEntry.data.planPath ?? null;
      currentPlanName = implEntry.data.planName ?? null;
    }

    if (currentPlanPath) {
      ctx.ui.notify(
        `Resumed implementation of: ${currentPlanName}`,
        "info",
      );
    }
  });
}

> pi can create extensions. Ask it to build one for your use case.

# Extensions

Extensions are TypeScript modules that extend pi's behavior. They can subscribe to lifecycle events, register custom tools callable by the LLM, add commands, and more.

> **Placement for /reload:** Put extensions in `~/.pi/agent/extensions/` (global) or `.pi/extensions/` (project-local) for auto-discovery. Use `pi -e ./path.ts` only for quick tests. Extensions in auto-discovered locations can be hot-reloaded with `/reload`.

**Key capabilities:**
- **Custom tools** - Register tools the LLM can call via `pi.registerTool()`
- **Event interception** - Block or modify tool calls, inject context, customize compaction
- **User interaction** - Prompt users via `ctx.ui` (select, confirm, input, notify)
- **Custom UI components** - Full TUI components with keyboard input via `ctx.ui.custom()` for complex interactions
- **Custom commands** - Register commands like `/mycommand` via `pi.registerCommand()`
- **Session persistence** - Store state that survives restarts via `pi.appendEntry()`
- **Custom rendering** - Control how tool calls/results and messages appear in TUI

**Example use cases:**
- Permission gates (confirm before `rm -rf`, `sudo`, etc.)
- Git checkpointing (stash at each turn, restore on branch)
- Path protection (block writes to `.env`, `node_modules/`)
- Custom compaction (summarize conversation your way)
- Conversation summaries (see `summarize.ts` example)
- Interactive tools (questions, wizards, custom dialogs)
- Stateful tools (todo lists, connection pools)
- External integrations (file watchers, webhooks, CI triggers)
- Games while you wait (see `snake.ts` example)

See [examples/extensions/](../examples/extensions/) for working implementations.

