/**
 * Plan Feature Extension
 *
 * /plan command that:
 * 1. Prompts for a feature name
 * 2. Creates a plan/<feature-name>.md file with a plan template
 * 3. Opens the plan file in VS Code
 * 4. Opens the plan content in the pi editor
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { mkdir, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { existsSync } from "node:fs";

const PLAN_DIR = "plan";

function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function generatePlanTemplate(featureName: string, timestamp: string): string {
  return `# ${featureName}

> **Status:** Draft  
> **Created:** ${timestamp}

## Overview

<!-- Briefly describe what this feature does and why it's needed -->

## Motivation

<!-- Why are we building this? What problem does it solve? -->

## Requirements

<!-- Concrete requirements. What must this feature do? -->

- 
- 

## Design / Approach

<!-- High-level design decisions, data flow, architecture choices -->

### Files to modify

<!-- Use \`tree\` or list files that will be changed -->

<!--
\`\`\`
path/to/file1.py - Description of change
path/to/file2.py - Description of change
\`\`\`
-->

### Database changes (if any)

<!-- Migration scripts, new tables, schema changes -->

### API changes (if any)

<!-- New endpoints, modified responses, request/response shapes -->

## Implementation Steps

1. 
2. 
3. 

## Testing Plan

<!-- How will this be tested? Unit tests, integration tests, manual steps -->

- [ ] Unit tests added/updated
- [ ] Integration tests pass
- [ ] Manual smoke test

## Edge Cases & Risks

<!-- Things that could go wrong, edge cases to handle -->

- 

## References

<!-- Links to docs, issues, related PRs -->

`;
}

export default function planFeatureExtension(pi: ExtensionAPI) {
  pi.registerCommand("plan", {
    description: "Create a new feature plan",
    handler: async (_args, ctx) => {
      // Step 1: Ask for the feature name
      const featureName = await ctx.ui.input(
        "Feature name:",
        "e.g. Add user authentication",
      );

      if (!featureName?.trim()) {
        ctx.ui.notify("Plan creation cancelled.", "warning");
        return;
      }

      const trimmedName = featureName.trim();
      const slug = slugify(trimmedName);
      const planDir = join(ctx.cwd, PLAN_DIR);
      const planPath = join(planDir, `${slug}.md`);

      // Step 2: Check if plan already exists
      if (existsSync(planPath)) {
        const overwrite = await ctx.ui.confirm(
          "Plan exists",
          `"${slug}.md" already exists. Open it instead?`,
        );

        if (overwrite) {
          // Open existing plan
          await pi.exec("code", [planPath]);
          ctx.ui.setEditorText(planPath);
          ctx.ui.notify(`Opening existing plan: plan/${slug}.md`, "info");
          return;
        }

        ctx.ui.notify("Plan creation cancelled.", "warning");
        return;
      }

      // Step 3: Create plan directory and file
      try {
        await mkdir(planDir, { recursive: true });

        const timestamp = new Date().toISOString().replace("T", " ").slice(0, 19);
        const content = generatePlanTemplate(trimmedName, timestamp);

        await writeFile(planPath, content, "utf-8");

        // Step 4: Open in VS Code
        const result = await pi.exec("code", [planPath]);

        if (result.code === 0 || existsSync("/snap/bin/code")) {
          ctx.ui.notify(
            `Plan created and opened in VS Code: plan/${slug}.md`,
            "success",
          );
        } else {
          ctx.ui.notify(
            `Plan created: plan/${slug}.md (VS Code not available)`,
            "info",
          );
        }

        // Step 5: (no longer loading plan content into pi's editor)
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        ctx.ui.notify(`Failed to create plan: ${message}`, "error");
      }
    },
  });

  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify(
      'Use /plan to create a feature plan. Plans are saved to "plan/" and opened in VS Code.',
      "info",
    );
  });
}

import { DatabaseSync } from "node:sqlite";
import { mkdirSync } from "node:fs";
import { dirname } from "node:path";

export interface UsageInsert {
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	source: "agent" | "extension";
	cwd: string | null;
	ts?: number; // defaults to Date.now()
}

export interface UsageRow {
	ts: number;
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	calls: number;
	source: string;
	cwd: string | null;
}

export interface GroupedRow {
	bucket: string;
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
	calls: number;
}

export interface Totals {
	calls: number;
	input: number;
	output: number;
	cacheRead: number;
	cacheWrite: number;
}

export type Breakdown = "day" | "week" | "month";

const SCHEMA = `
CREATE TABLE IF NOT EXISTS usage (
  id          INTEGER PRIMARY KEY AUTOINCREMENT,
  ts          INTEGER NOT NULL,
  provider    TEXT NOT NULL,
  model       TEXT NOT NULL,
  input       INTEGER NOT NULL,
  output      INTEGER NOT NULL,
  cache_read  INTEGER NOT NULL DEFAULT 0,
  cache_write INTEGER NOT NULL DEFAULT 0,
  calls       INTEGER NOT NULL DEFAULT 1,
  source      TEXT NOT NULL DEFAULT 'agent',
  cwd         TEXT
);
CREATE INDEX IF NOT EXISTS idx_ts ON usage(ts);
CREATE INDEX IF NOT EXISTS idx_provider_model ON usage(provider, model);
`;

function bucketExpr(breakdown: Breakdown): string {
	switch (breakdown) {
		case "day":
			// strftime on unixepoch seconds in UTC. Buckets in UTC so the
			// grouping is deterministic across timezone changes.
			return `strftime('%Y-%m-%d', ts / 1000, 'unixepoch')`;
		case "week":
			return `strftime('%Y-W%W', ts / 1000, 'unixepoch')`;
		case "month":
			return `strftime('%Y-%m', ts / 1000, 'unixepoch')`;
	}
}

function rowsFrom<T>(result: unknown): T[] {
	// node:sqlite returns an array of objects with a null prototype.
	// Clone them so they compare as plain objects via deep-equal helpers.
	if (!Array.isArray(result)) return [];
	return result.map((row) => ({ ...(row as object) })) as T[];
}

function rowFrom<T>(result: unknown): T {
	if (!result || typeof result !== "object") {
		throw new Error("Expected single row from query");
	}
	return { ...(result as object) } as T;
}

export class TokenDb {
	private db: DatabaseSync;

	constructor(dbPath: string) {
		mkdirSync(dirname(dbPath), { recursive: true });
		this.db = new DatabaseSync(dbPath);
		// WAL is supported on node:sqlite via the journal_mode pragma.
		this.db.exec("PRAGMA journal_mode = WAL");
		this.db.exec(SCHEMA);
	}

	insert(row: UsageInsert): void {
		const ts = row.ts ?? Date.now();
		this.db
			.prepare(
				`INSERT INTO usage (ts, provider, model, input, output, cache_read, cache_write, source, cwd)
				 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			)
			.run(
				ts,
				row.provider,
				row.model,
				row.input,
				row.output,
				row.cacheRead,
				row.cacheWrite,
				row.source,
				row.cwd,
			);
	}

	query(from: Date, to: Date, cwd?: string): UsageRow[] {
		const sql = cwd
			? `SELECT ts, provider, model, input, output, cache_read AS cacheRead, cache_write AS cacheWrite, calls, source, cwd
			   FROM usage
			   WHERE ts >= ? AND ts < ? AND cwd = ?
			   ORDER BY ts`
			: `SELECT ts, provider, model, input, output, cache_read AS cacheRead, cache_write AS cacheWrite, calls, source, cwd
			   FROM usage
			   WHERE ts >= ? AND ts < ?
			   ORDER BY ts`;
		const params = cwd ? [from.getTime(), to.getTime(), cwd] : [from.getTime(), to.getTime()];
		return rowsFrom<UsageRow>(this.db.prepare(sql).all(...params));
	}

	queryGrouped(from: Date, to: Date, breakdown: Breakdown, cwd?: string): GroupedRow[] {
		const bucket = bucketExpr(breakdown);
		const cwdClause = cwd ? " AND cwd = ?" : "";
		const params: (number | string)[] = cwd
			? [from.getTime(), to.getTime(), cwd]
			: [from.getTime(), to.getTime()];

		const sql = `
			SELECT
				${bucket} AS bucket,
				provider,
				model,
				SUM(input) AS input,
				SUM(output) AS output,
				SUM(cache_read) AS cacheRead,
				SUM(cache_write) AS cacheWrite,
				SUM(calls) AS calls
			FROM usage
			WHERE ts >= ? AND ts < ?${cwdClause}
			GROUP BY bucket, provider, model
			ORDER BY bucket ASC, provider ASC, model ASC
		`;
		return rowsFrom<GroupedRow>(this.db.prepare(sql).all(...params));
	}

	totals(from: Date, to: Date, cwd?: string): Totals {
		const cwdClause = cwd ? " AND cwd = ?" : "";
		const params: (number | string)[] = cwd
			? [from.getTime(), to.getTime(), cwd]
			: [from.getTime(), to.getTime()];

		const sql = `
			SELECT
				COALESCE(SUM(calls), 0) AS calls,
				COALESCE(SUM(input), 0) AS input,
				COALESCE(SUM(output), 0) AS output,
				COALESCE(SUM(cache_read), 0) AS cacheRead,
				COALESCE(SUM(cache_write), 0) AS cacheWrite
			FROM usage
			WHERE ts >= ? AND ts < ?${cwdClause}
		`;
		const result = this.db.prepare(sql).get(...params);
		return rowFrom<Totals>(result);
	}

	close(): void {
		this.db.close();
	}
}

/**
 * pi-token-tracker
 *
 * A pi extension that tracks model token usage across the main agent loop
 * and extension out-of-band calls, stored in SQLite, displayed via a
 * `/token-usage` command with configurable time ranges and breakdowns.
 *
 * Listens to `message_end` for main-loop assistant usage and the shared
 * `pi.events` bus for `model:usage` events from other extensions.
 */

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { matchesKey, Key } from "@earendil-works/pi-tui";
import { join } from "node:path";
import { TokenDb } from "./db.ts";
import {
	type RangeOption,
	type BreakdownOption,
	getBreakdownsForRange,
	nextRange,
	nextBreakdown,
	rangeStartDate,
	rangeLabel,
	renderHeader,
	renderTable,
	renderFooter,
} from "./render.ts";
import type { Breakdown } from "./db.ts";

// Resolve DB path: honor $PI_TOKEN_DB for tests / power users, otherwise
// place the SQLite file in the standard pi agent data dir.
function defaultDbPath(): string {
	const envHome = process.env.HOME ?? process.env.USERPROFILE ?? "~";
	return join(envHome, ".pi", "agent", "data", "token-usage.db");
}

const DB_PATH = process.env.PI_TOKEN_DB ?? defaultDbPath();

/** Payload other extensions emit onto `pi.events` to report OOB usage. */
export interface ModelUsageEvent {
	provider: string;
	model: string;
	input: number;
	output: number;
	cacheRead?: number;
	cacheWrite?: number;
}

export default function (pi: ExtensionAPI) {
	const db = new TokenDb(DB_PATH);

	// --- Main agent loop: track assistant messages ---
	pi.on("message_end", async (event, ctx) => {
		const msg = event.message;
		if (msg.role !== "assistant") return;

		const usage = msg.usage;
		db.insert({
			provider: msg.provider,
			model: msg.model,
			input: usage.input ?? 0,
			output: usage.output ?? 0,
			cacheRead: usage.cacheRead ?? 0,
			cacheWrite: usage.cacheWrite ?? 0,
			source: "agent",
			cwd: ctx.cwd,
		});
	});

	// --- Extension out-of-band calls ---
	// The EventBus channel is untyped (`data: unknown`), so we narrow it
	// defensively before inserting.
	pi.events.on("model:usage", ((raw: unknown) => {
		const data = raw as Partial<ModelUsageEvent> | null | undefined;
		if (!data || typeof data !== "object") return;
		const provider = typeof data.provider === "string" ? data.provider : "unknown";
		const model = typeof data.model === "string" ? data.model : "unknown";
		const input = Number.isFinite(data.input) ? (data.input as number) : 0;
		const output = Number.isFinite(data.output) ? (data.output as number) : 0;
		const cacheRead = Number.isFinite(data.cacheRead) ? (data.cacheRead as number) : 0;
		const cacheWrite = Number.isFinite(data.cacheWrite) ? (data.cacheWrite as number) : 0;
		db.insert({
			provider,
			model,
			input,
			output,
			cacheRead,
			cacheWrite,
			source: "extension",
			cwd: process.cwd(),
		});
	}) as (data: unknown) => void);

	// --- Cleanup on session shutdown ---
	pi.on("session_shutdown", () => {
		db.close();
	});

	// --- /token-usage command ---
	pi.registerCommand("token-usage", {
		description:
			"Show token usage breakdown by model with configurable time ranges",
		handler: async (_args, ctx) => {
			if (!ctx.hasUI) {
				ctx.ui.notify("Token usage requires interactive mode", "warning");
				return;
			}

			let range: RangeOption = "week";
			let breakdown: BreakdownOption = getBreakdownsForRange(range)[0]!;

			await ctx.ui.custom<void>((tui, theme, _kb, done) => {
				const renderView = (): string[] => {
					const lines: string[] = [];

					const startDate = rangeStartDate(range);
					const now = new Date();
					const rows = db.queryGrouped(
						startDate,
						now,
						breakdown as Breakdown,
						undefined,
					);
					const totals = db.totals(startDate, now);

					lines.push(renderHeader(theme, startDate, range));
					lines.push(
						...renderTable(
							rows.map((r) => ({ ...r })),
							totals,
							breakdown as Breakdown,
							theme,
							process.stdout.columns ?? 80,
						),
					);
					lines.push("");
					lines.push(
						renderFooter(
							theme,
							range,
							breakdown,
							getBreakdownsForRange(range).length > 1,
						),
					);

					return lines;
				};

				let cachedLines: string[] = renderView();

				return {
					render(_width: number): string[] {
						return cachedLines;
					},
					invalidate(): void {
						cachedLines = renderView();
					},
					handleInput(data: string): void {
						if (matchesKey(data, "escape") || data === "q") {
							done();
						} else if (matchesKey(data, Key.ctrl("r"))) {
							range = nextRange(range);
							breakdown = getBreakdownsForRange(range)[0]!;
							cachedLines = renderView();
							tui.requestRender();
						} else if (matchesKey(data, Key.tab)) {
							breakdown = nextBreakdown(range, breakdown);
							cachedLines = renderView();
							tui.requestRender();
						}
					},
				};
			});
		},
	});
}

