        return "tbd"

    def _do_update_rates(self) -> tuple[Response, int]:
        """Core logic to update fund data from all bank APIs."""
        try:
            funds = self.get_all_funds()
            updated_count = 0
            skipped = []

            with ThreadPoolExecutor(max_workers=8) as executor:
                future_to_fund = {}
                for fund in funds:
                    bank_name = fund.split(" ")[0]
                    if bank_name not in self.handlers:
                        logger.warning(f"No handler found for bank: {bank_name}")
                        skipped.append(fund)
                        continue
                    future = executor.submit(self.handlers[bank_name].get_rate, fund)
                    future_to_fund[future] = fund

                for future in as_completed(future_to_fund):
                    fund = future_to_fund[future]
                    try:
                        rate = future.result()
                        self.db_inserter.insert_value(date.today(), fund, rate.value)
                        updated_count += 1
                    except FundNotFoundError as fnf:
                        logger.warning(f"Fund not found: {fnf}")
                    except (BankAPIError, DataParsingError) as api_err:
                        logger.error(f"API error for {fund}: {api_err}")
                    except StonksError as s_err:
                        logger.error(f"General domain error for {fund}: {s_err}")
                    except Exception as ex:
                        logger.error(f"Unexpected error for {fund}: {ex}")

            # Invalidate funds cache after update
            self._funds_cache = None
            logger.info(f"Successfully updated {updated_count} funds")
            return jsonify({
                "status": "success",
                "message": f"Data updated successfully for {updated_count} funds",
                "date": str(date.today())
            }), 200

        except StonksError as s_err:
            logger.error(f"Domain error in data update: {s_err}")
            return jsonify({'error': str(s_err)}), 500
        except Exception as err:
            logger.error(f"Unexpected error in data update: {err}")
            return jsonify({'error': f'Unexpected error: {err}'}), 500

    def update_rates(self) -> tuple[Response, int]:
        """Update fund data from all bank APIs using parallel fetching."""
        return self._do_update_rates()

